import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    previous_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > previous_limit:
            csv.field_size_limit(len(raw_csv))
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=";"))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    width = max(len(record) for record in records)
    columns = records[0] + [""] * (width - len(records[0]))
    rows = [row + [""] * (width - len(row)) for row in records[1:]]
    return {"columns": columns, "rows": rows}
